mapper.select:
SELECT ep.id, ep.eval_year, ep.eval_quarter, ep.control_id, c.control_code, c.control_name, c.domain, ep.assignee, ep.planned_start_date, ep.planned_end_date, ep.actual_start_date, ep.actual_end_date, ep.sampling_count, ep.sampling_method, ep.status, ep.created_at, ep.updated_at, ep.created_by FROM itgc_eval_plan ep JOIN itgc_control c ON c.id = ep.control_id
AND ep.eval_year = #{evalYear}
AND ep.eval_quarter = #{evalQuarter}
AND c.domain = #{domain}
AND ep.status = #{status}
ORDER BY ep.eval_year DESC, ep.eval_quarter, c.control_code

mapper.insert:
INSERT INTO itgc_eval_plan (
    eval_year, eval_quarter, control_id, assignee,
    planned_start_date, planned_end_date, sampling_count, sampling_method,
    status, created_by
) VALUES (
    #{evalYear}, #{evalQuarter}, #{controlId}, #{assignee},
    #{plannedStartDate}, #{plannedEndDate}, #{samplingCount}, #{samplingMethod},
    #{status}, #{createdBy}
)

INSERT INTO itgc_eval_sample (
    eval_plan_id, sample_no, transaction_id, transaction_date,
    description, evidence_file, test_result, exception_reason,
    tester, test_date, remarks
) VALUES (
    #{evalPlanId}, #{sampleNo}, #{transactionId}, #{transactionDate},
    #{description}, #{evidenceFile}, #{testResult}, #{exceptionReason},
    #{tester}, #{testDate}, #{remarks}
)

INSERT INTO itgc_eval_result (
    eval_plan_id, total_samples, pass_count,
    exception_count, not_applicable_count, conclusion,
    evaluator_opinion, status, created_by
) VALUES (
    #{evalPlanId}, #{totalSamples}, #{passCount},
    #{exceptionCount}, #{notApplicableCount}, #{conclusion},
    #{evaluatorOpinion}, #{status}, #{createdBy}
)
